/// <reference lib="webworker" />
import { precacheAndRoute } from 'workbox-precaching';

declare let self: ServiceWorkerGlobalScope;

// Precache assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST || []);

// Cache name for offline synchronization queue
const SYNC_CACHE_NAME = 'maths-adventure-sync-v1';

// Synchronize cached player stats to the server
async function syncCachedStatsToServer(): Promise<{ success: boolean; count: number; error?: string }> {
  try {
    const cache = await caches.open(SYNC_CACHE_NAME);
    const queueResponse = await cache.match('/local-sync-queue');
    if (!queueResponse) {
      return { success: true, count: 0 };
    }

    const queue: any[] = await queueResponse.json();
    if (!Array.isArray(queue) || queue.length === 0) {
      return { success: true, count: 0 };
    }

    // Take the latest state or send batched payloads
    const latestItem = queue[queue.length - 1];

    const response = await fetch('/api/sync/stats', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(latestItem),
    });

    if (response.ok) {
      // Clear queue from cache on successful server synchronization
      await cache.delete('/local-sync-queue');

      // Notify all open client windows
      const clients = await self.clients.matchAll();
      clients.forEach((client) => {
        client.postMessage({
          type: 'SYNC_SUCCESS',
          timestamp: new Date().toISOString(),
          syncedCount: queue.length,
        });
      });

      return { success: true, count: queue.length };
    } else {
      throw new Error(`Server returned status ${response.status}`);
    }
  } catch (err: any) {
    const clients = await self.clients.matchAll();
    clients.forEach((client) => {
      client.postMessage({
        type: 'SYNC_ERROR',
        error: err?.message || 'Sync failed',
      });
    });
    return { success: false, count: 0, error: err?.message };
  }
}

// Background Sync Event (triggered automatically by browser when connection restores)
self.addEventListener('sync' as any, (event: any) => {
  if (event.tag === 'sync-player-stats') {
    event.waitUntil(syncCachedStatsToServer());
  }
});

// Listen to messages from main window client
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'QUEUE_STATS_FOR_SYNC') {
    // Store in sync cache
    event.waitUntil(
      (async () => {
        const cache = await caches.open(SYNC_CACHE_NAME);
        const currentQueueResp = await cache.match('/local-sync-queue');
        let queue: any[] = [];
        if (currentQueueResp) {
          try {
            queue = await currentQueueResp.json();
          } catch {
            queue = [];
          }
        }
        queue.push(event.data.payload);
        // Keep max 50 items in queue
        if (queue.length > 50) {
          queue = queue.slice(queue.length - 50);
        }
        await cache.put(
          '/local-sync-queue',
          new Response(JSON.stringify(queue), {
            headers: { 'Content-Type': 'application/json' },
          })
        );

        // If online right now, attempt immediate sync
        if (navigator.onLine) {
          await syncCachedStatsToServer();
        }
      })()
    );
  }

  if (event.data && event.data.type === 'FORCE_SYNC_NOW') {
    event.waitUntil(syncCachedStatsToServer());
  }
});

// Claim clients immediately on activate
self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});
